//! Normal unprofiled queue lifecycle carrier; setup and acceptance are separate.
mod clock;
mod fixture;
mod metadata;
use super::PendingInitialDiagnostics;
use super::pending::InitialDiagnosticsJob;
use sha2::{Digest, Sha256};
use std::fmt::Write;
use std::hint::black_box;
use std::time::{Duration, Instant};
use tower_lsp::lsp_types::Url;

fn enqueue(queue: &mut PendingInitialDiagnostics, inputs: &[(Url, InitialDiagnosticsJob)]) {
    for (uri, job) in inputs {
        queue.insert_with_continuation(
            uri.clone(),
            job.version,
            job.not_before,
            job.cause,
            job.sync.clone(),
            job.continuation.clone(),
        );
    }
}

fn drain(queue: &mut PendingInitialDiagnostics, now: Instant, seen: &mut Vec<(Url, i32)>) {
    while let Some((uri, job)) = queue.take_sync() {
        queue.complete_sync(&uri, job.sequence);
        drop(black_box((uri, job)));
    }
    loop {
        if let Some(job) = queue.take_preparation() {
            drop(black_box(job));
            continue;
        }
        if queue.next_not_before().is_none() {
            break;
        }
        let (uri, job) = queue.take_ready(now).unwrap();
        seen.push((uri, job.version));
        drop(black_box(job));
    }
}

fn check(seen: &mut Vec<(Url, i32)>, inputs: &[(Url, InitialDiagnosticsJob)], version: i32) {
    let mut expected: Vec<_> = inputs
        .iter()
        .map(|(uri, _)| (uri.clone(), version))
        .collect();
    expected.sort_unstable();
    seen.sort_unstable();
    assert_eq!(
        *seen, expected,
        "every actual URI/version exactly once; duplicates are not collapsed"
    );
    seen.clear();
}

fn timed<R>(body: impl FnOnce() -> R) -> (R, clock::Timing) {
    let thread = clock::cpu(libc::CLOCK_THREAD_CPUTIME_ID);
    let process = clock::cpu(libc::CLOCK_PROCESS_CPUTIME_ID);
    let began = Instant::now();
    let result = body();
    let wall_ns = began.elapsed().as_nanos();
    let thread_cpu_ns = clock::cpu(libc::CLOCK_THREAD_CPUTIME_ID) - thread;
    let process_cpu_ns = clock::cpu(libc::CLOCK_PROCESS_CPUTIME_ID) - process;
    (
        result,
        clock::Timing {
            wall_ns,
            thread_cpu_ns,
            process_cpu_ns,
        },
    )
}

fn status() -> String {
    std::fs::read_to_string("/proc/self/status")
        .unwrap()
        .lines()
        .filter(|line| {
            line.starts_with("VmRSS:") || line.starts_with("VmHWM:") || line.starts_with("Threads:")
        })
        .collect::<Vec<_>>()
        .join("\n")
}

#[test]
fn normal_queue_lifecycle() {
    assert!(
        !cfg!(feature = "micro-profiling"),
        "normal timing has no source counters or profiling allocator"
    );
    let count = std::env::var("VIZE_QUEUE_COUNT")
        .unwrap()
        .parse::<usize>()
        .unwrap();
    assert!([1, 10, 100].contains(&count));
    let setup = Instant::now();
    let inputs = fixture::capture(count);
    let setup_ns = setup.elapsed().as_nanos();
    let manifest = serde_json::to_vec(&inputs.manifest).unwrap();
    let mut input_sha256 = String::with_capacity(64);
    for byte in Sha256::digest(&manifest) {
        write!(&mut input_sha256, "{byte:02x}").unwrap();
    }
    let after_setup = status();
    let (_, empty_clock_ns) = timed(|| black_box(()));
    let mut seen = Vec::with_capacity(count);
    let mut moves: Vec<_> = inputs
        .opens
        .iter()
        .map(|(uri, job)| (uri.clone(), job.version))
        .collect();
    let (_, observer_buffer_move_ns) = timed(|| seen.extend(moves.drain(..)));
    seen.clear();
    let now = Instant::now();
    let (mut queue, enqueue_ns) = timed(|| {
        let mut queue = PendingInitialDiagnostics::default();
        enqueue(&mut queue, &inputs.opens);
        queue
    });
    assert_eq!(queue.jobs.len(), count);
    let before_drain = status();
    let (_, drain_ns) = timed(|| drain(&mut queue, now + Duration::from_secs(2), &mut seen));
    check(&mut seen, &inputs.opens, 1);
    assert!(queue.jobs.is_empty());
    let after_drain = status();
    let open_retained = metadata::snapshot(&queue);
    enqueue(&mut queue, &inputs.opens);
    let (_, dense_edit_ns) = timed(|| {
        for round in &inputs.edits {
            enqueue(&mut queue, round);
        }
    });
    for (uri, _) in &inputs.opens {
        let job = queue.jobs.get(uri).unwrap();
        assert_eq!(job.version, 4);
        assert_eq!(job.sync.as_ref().unwrap().version, 4);
    }
    let (_, dense_drain_ns) = timed(|| drain(&mut queue, now + Duration::from_secs(2), &mut seen));
    check(&mut seen, &inputs.opens, 4);
    assert!(queue.jobs.is_empty());
    let dense_retained = metadata::snapshot(&queue);
    enqueue(&mut queue, &inputs.opens);
    let (_, close_reopen_ns) = timed(|| {
        for (uri, _) in &inputs.opens {
            queue.jobs.remove(uri);
        }
        enqueue(&mut queue, &inputs.reopened);
    });
    let (_, reopened_drain_ns) =
        timed(|| drain(&mut queue, now + Duration::from_secs(2), &mut seen));
    check(&mut seen, &inputs.reopened, 1);
    assert!(queue.jobs.is_empty());
    let reopened_retained = metadata::snapshot(&queue);
    let report = serde_json::json!({
        "source": std::env::var("VIZE_QUEUE_SOURCE").unwrap(),
        "role": std::env::var("VIZE_QUEUE_ROLE").unwrap(),
        "unique_uris": count, "input_sha256":input_sha256,
        "scope":"normal single-thread production queue methods and real captured URI-bound payloads; paused consumers, no Go/RPC/native throughput or cold-LSP claim",
        "setup_wall_ns":setup_ns,"empty_clock":empty_clock_ns,"observer_buffer_move":observer_buffer_move_ns,
        "observer_scope":"returned URI/version moves enter a preallocated validation buffer during drain; sorting/exact-array checking and buffer destruction stay outside timing, identically for both roles",
        "retained_metadata":{"after_open_drain":open_retained,"after_dense_drain":dense_retained,"after_reopened_drain":reopened_retained},
        "timed":{"enqueue":enqueue_ns,"open_drain":drain_ns,"three_dense_edit_rounds":dense_edit_ns,"dense_drain":dense_drain_ns,"close_reopen":close_reopen_ns,"reopened_drain":reopened_drain_ns},
        "rust_process_status":{"after_setup":after_setup,"before_drain":before_drain,"after_drain":after_drain,"final":status()},
        "cpu_clock_scope":"thread CPU belongs to this Rust test thread; process CPU also includes other Rust-process threads, no Node children. CPU clocks bracket wall and include observer clock reads; empty calibration is reported without subtraction",
        "memory_scope":"VmRSS/VmHWM belong to this Rust libtest process including setup; not simultaneous process-tree RSS or live Rust allocation bytes",
        "deadline_scope":"actual captured not_before values are copied unchanged; drain uses a future ready instant without sleeping; this excludes interactive grace from the component window",
        "payload":"actual didOpen continuations and didChange parser diagnostics retained unchanged, never retargeted; prior snapshots may be stale exactly as in a real queued burst",
        "production_workers_unchanged":2, "running_native_workers_in_this_component_carrier":0,
        "profiling":false,"build_configuration":{"test_cfg":cfg!(test),"debug_assertions":cfg!(debug_assertions),"micro_profiling":cfg!(feature="micro-profiling")},"raw_input_manifest":inputs.manifest,
    });
    std::fs::write(
        std::env::var("VIZE_QUEUE_EVIDENCE").unwrap(),
        serde_json::to_vec_pretty(&report).unwrap(),
    )
    .unwrap();
}

//! Actual didOpen/didChange payloads; native consumers stay paused in this component carrier.
use super::super::pending::InitialDiagnosticsJob;
use super::super::{InitialDiagnosticsScheduler, MaestroServer, PendingInitialDiagnostics};
use std::path::PathBuf;
use std::sync::{Arc, mpsc};
use tower_lsp::lsp_types::{
    DidChangeTextDocumentParams, DidOpenTextDocumentParams, TextDocumentContentChangeEvent,
    TextDocumentItem, Url, VersionedTextDocumentIdentifier,
};
use tower_lsp::{LanguageServer, LspService};

pub(super) struct Inputs {
    pub(super) opens: Vec<(Url, InitialDiagnosticsJob)>,
    pub(super) edits: Vec<Vec<(Url, InitialDiagnosticsJob)>>,
    pub(super) reopened: Vec<(Url, InitialDiagnosticsJob)>,
    pub(super) manifest: Vec<serde_json::Value>,
    _service: LspService<MaestroServer>,
    _receiver: mpsc::Receiver<()>,
}

pub(super) fn capture(count: usize) -> Inputs {
    let root = PathBuf::from(std::env::var("VIZE_QUEUE_PROJECT").unwrap());
    assert!(
        !root.exists(),
        "the workflow owns and recreates only this fixed project path"
    );
    std::fs::create_dir_all(&root).unwrap();
    std::fs::write(
        root.join("vite.config.mjs"),
        "export default { vue: { languageServer: { hover: true } } };\n",
    )
    .unwrap();
    std::fs::write(
        root.join("tsconfig.json"),
        r#"{"compilerOptions":{"strict":true,"noEmit":true},"include":["*.vue"]}"#,
    )
    .unwrap();
    let pending = Arc::new(parking_lot::Mutex::new(PendingInitialDiagnostics::default()));
    let queue = Arc::clone(&pending);
    let (sender, receiver) = mpsc::sync_channel(1);
    let (service, socket) = LspService::new(|client| {
        let mut server = MaestroServer::new(client);
        server.initial_diagnostics = Some(InitialDiagnosticsScheduler {
            sender: Some(sender),
            sync_sender: None,
            worker_owned: false,
            pending: queue,
        });
        server
    });
    // This measures queue work and authentic payload cloning, not RPC delivery.
    // A closed client avoids unconsumed setup notifications; no native worker starts.
    drop(socket);
    let server = service.inner();
    server.state.set_workspace_root(root.clone());
    server.state.load_workspace_config(&root);
    server
        .state
        .apply_lsp_initialization_options(Some(&serde_json::json!({
            "editor":true,"lint":true,"typecheck":true,"ecosystem":false
        })));
    let mut manifest = Vec::new();
    let mut opens = Vec::new();
    for index in 0..count {
        let file = root.join(format!("Component{index:04}.vue"));
        let uri = Url::from_file_path(&file).unwrap();
        let text = source(index, 1);
        std::fs::write(&file, &text).unwrap();
        crate::runtime::block_on(server.open_document(DidOpenTextDocumentParams {
            text_document: TextDocumentItem::new(uri.clone(), "vue".into(), 1, text.clone()),
        }));
        let job = pending.lock().jobs.get(&uri).unwrap().clone();
        assert_eq!(job.version, 1);
        assert!(
            job.continuation.is_some(),
            "capture a real URI-bound continuation"
        );
        manifest.push(serde_json::json!({"uri":uri,"version":1,"source":text}));
        opens.push((uri, job));
    }
    let mut edits = Vec::new();
    for version in 2..=4 {
        let mut round = Vec::new();
        for (index, (uri, _)) in opens.iter().enumerate() {
            let text = source(index, version);
            crate::runtime::block_on(server.did_change(DidChangeTextDocumentParams {
                text_document: VersionedTextDocumentIdentifier {
                    uri: uri.clone(),
                    version,
                },
                content_changes: vec![TextDocumentContentChangeEvent {
                    range: None,
                    range_length: None,
                    text: text.clone(),
                }],
            }));
            let job = pending.lock().jobs.get(uri).unwrap().clone();
            assert_eq!(job.version, version);
            assert!(job.continuation.is_none());
            let sync = job
                .sync
                .as_ref()
                .expect("actual didChange must retain its sync payload");
            assert_eq!(sync.version, version);
            assert!(
                !sync.diagnostics.is_empty(),
                "real parser diagnostics, not an empty fabricated payload"
            );
            manifest.push(serde_json::json!({"uri":uri,"version":version,"source":text,"diagnostics":sync.diagnostics}));
            round.push((uri.clone(), job));
        }
        edits.push(round);
    }
    let mut reopened = Vec::new();
    for (index, (uri, _)) in opens.iter().enumerate() {
        server.state.documents.close(uri);
        server
            .initial_diagnostics
            .as_ref()
            .unwrap()
            .discard_closed(uri, &server.state.documents);
        let text = source(index, 100);
        crate::runtime::block_on(server.open_document(DidOpenTextDocumentParams {
            text_document: TextDocumentItem::new(uri.clone(), "vue".into(), 1, text.clone()),
        }));
        let job = pending.lock().jobs.get(uri).unwrap().clone();
        assert_eq!(job.version, 1);
        assert!(job.continuation.is_some());
        manifest
            .push(serde_json::json!({"uri":uri,"version":1,"generation":"reopened","source":text}));
        reopened.push((uri.clone(), job));
    }
    Inputs {
        opens,
        edits,
        reopened,
        manifest,
        _service: service,
        _receiver: receiver,
    }
}

fn source(index: usize, version: i32) -> String {
    // A real template parse error guarantees a nonempty sync diagnostic payload.
    format!(
        "<script setup lang=\"ts\">const value{index} = {version};</script>\n<template><div>🌱{{{{ value{index} }}}}</template>\n"
    )
}

