//! Linux CPU clocks for the test caller; no source-function instrumentation.
#[derive(serde::Serialize)]
pub(super) struct Timing {
    pub(super) wall_ns: u128,
    pub(super) thread_cpu_ns: u64,
    pub(super) process_cpu_ns: u64,
}

pub(super) fn cpu(clock: libc::clockid_t) -> u64 {
    let mut value = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: value is an initialized, exclusively borrowed timespec for the
    // synchronous syscall; the pointer stays live and never escapes it.
    let result = unsafe { libc::clock_gettime(clock, &mut value) };
    assert_eq!(
        result, 0,
        "unsupported CPU clocks must fail, never report zero"
    );
    let seconds = u64::try_from(value.tv_sec).unwrap();
    let nanos = u64::try_from(value.tv_nsec).unwrap();
    assert!(nanos < 1_000_000_000);
    seconds
        .checked_mul(1_000_000_000)
        .unwrap()
        .checked_add(nanos)
        .unwrap()
}
